	static Stream<IsolationLevel> isolationLevels() {
		return Stream.of(IsolationLevels.NONE, IsolationLevels.SNAPSHOT_READ);
	}

	private static Statement statement(String value) {
		return statementWithContext(value, null);
	}

	private static Statement statementWithContext(String value, String context) {
		var valueFactory = SimpleValueFactory.getInstance();
		var subject = valueFactory.createIRI("urn:subject:" + value);
		var predicate = valueFactory.createIRI("urn:predicate");
		var object = valueFactory.createLiteral(value);
		if (context == null) {
			return valueFactory.createStatement(subject, predicate, object);
		}
		return valueFactory.createStatement(subject, predicate, object,
				valueFactory.createIRI("urn:context:" + context));
	}

